import { LotteryBrandListPage } from '../../../pages/lottery-brand/lottery-brand-list.page';
import { Logger } from '../../logger';

const logger = new Logger();

/** Only brand codes generated by the test data factory start with "AT"; nothing else is ever touched. */
const AUTOMATION_CODE = /^AT/i;

/**
 * Best-effort afterEach cleanup: delete (soft) the brands a test created.
 * BigWin has no hard delete for brands, so deleted test brands remain in the "Deleted" tab.
 */
export async function cleanupBrands(listPage: LotteryBrandListPage, codes: string[]): Promise<void> {
  const own = [...new Set(codes.map((c) => c.trim()))].filter((c) => AUTOMATION_CODE.test(c));
  if (own.length === 0) return;
  try {
    await listPage.open();
  } catch {
    logger.warn('⚠️ Brand cleanup could not open the Lottery Brands list');
    return;
  }
  for (const code of own) {
    try {
      if (!(await listPage.brandIsListed(code))) continue;
      await listPage.deleteBrand(code);
      logger.info(`🧹 Cleaned up brand: ${code}`);
    } catch (error) {
      logger.warn(`⚠️ Could not clean up brand: ${code} - ${String(error).split('\n')[0]}`);
    }
  }
}
